    Write-Host @"
La Fase 10 genererebbe 19 file:

- board prenotazioni live;
- dettaglio e timeline prenotazione;
- check-in atomico con apertura sessione tavolo POS;
- azioni check-in, seat, complete e no-show;
- expectedVersion e mutationId;
- feed cursorizzato sugli outbox events;
- test backend e frontend;
- nessuna migrazione database.
"@

    return
}

Write-Step -Message 'Formattazione backend Fase 10'

Invoke-Checked `
    -FilePath $npxCommand `
    -ArgumentList @(
        'prettier',
        '--write',
        'apps/api/src/control-center/dto/reservation-feed-query.dto.ts',
        'apps/api/src/control-center/dto/reservation-operation.dto.ts',
        'apps/api/src/control-center/reservation-operations-policy.ts',
        'apps/api/src/control-center/reservation-operations-policy.spec.ts',
        'apps/api/src/control-center/reservation-operations.service.ts',
        'apps/api/src/control-center/control-center.service.ts',
        'apps/api/src/control-center/control-center.controller.ts',
        'apps/api/src/control-center/control-center.module.ts'
    ) `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

Write-Step -Message 'Formattazione frontend Fase 10'

Invoke-Checked `
    -FilePath $npxCommand `
    -ArgumentList @(
        'prettier',
        '--write',
        'app/api/control-center/reservation-feed/route.ts',
        'app/api/control-center/reservations/[reservationId]/route.ts',
        'app/api/control-center/reservations/[reservationId]/actions/[action]/route.ts',
        'components/merchant/reservation-live-sync.tsx',
        'components/merchant/reservation-actions.tsx',
        'app/merchant/reservations/page.tsx',
        'app/merchant/reservations/[reservationId]/page.tsx',
        'lib/control-center/types.ts',
        'app/globals.css'
    ) `
    -WorkingDirectory $webRoot | ForEach-Object {
        Write-Host $_
    }

Invoke-Checked `
    -FilePath $npxCommand `
    -ArgumentList @(
        'prettier',
        '--write',
        'scripts/verify-phase-10-reservation-operations.mjs',
        'docs/phase-2/reservation-operations.md'
    ) `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

$localBootstrapPath = Join-Path `
    -Path $repositoryRoot `
    -ChildPath 'scripts\bootstrap-platform-admin.local.ts'

if (Test-Path -LiteralPath $localBootstrapPath) {
    Write-Step -Message 'Formattazione helper bootstrap locale'

    Invoke-Checked `
        -FilePath $npxCommand `
        -ArgumentList @(
            'prettier',
            '--write',
            'scripts/bootstrap-platform-admin.local.ts'
        ) `
        -WorkingDirectory $repositoryRoot | ForEach-Object {
            Write-Host $_
        }
}

Write-Step -Message 'Verifica strutturale Fase 10'

Invoke-Checked `
    -FilePath 'node' `
    -ArgumentList @(
        'scripts/verify-phase-10-reservation-operations.mjs'
    ) `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

Write-Step -Message 'Lint backend'

Invoke-Checked `
    -FilePath $npmCommand `
    -ArgumentList @('run', 'lint') `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

if (-not $SkipTests) {
    Write-Step -Message 'Test backend'

    Invoke-Checked `
        -FilePath $npmCommand `
        -ArgumentList @('test') `
        -WorkingDirectory $repositoryRoot | ForEach-Object {
            Write-Host $_
        }
}

Write-Step -Message 'Build backend'

Invoke-Checked `
    -FilePath $npmCommand `
    -ArgumentList @('run', 'build') `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

Write-Step -Message 'Lint frontend'

Invoke-Checked `
    -FilePath $npmCommand `
    -ArgumentList @('run', 'lint') `
    -WorkingDirectory $webRoot | ForEach-Object {
        Write-Host $_
    }

if (-not $SkipTests) {
    Write-Step -Message 'Test frontend'

    Invoke-Checked `
        -FilePath $npmCommand `
        -ArgumentList @('run', 'test') `
        -WorkingDirectory $webRoot | ForEach-Object {
            Write-Host $_
        }
}

$hadNodeEnvironment = Test-Path Env:NODE_ENV
$previousNodeEnvironment = if ($hadNodeEnvironment) {
    $env:NODE_ENV
}
else {
    $null
}

try {
    Write-Step -Message 'Build Next.js pulito'

    $env:NODE_ENV = 'production'

    if (Test-Path -LiteralPath $nextBuildDirectory) {
        Remove-Item `
            -LiteralPath $nextBuildDirectory `
            -Recurse `
            -Force
        Write-Host "Cache Next.js rimossa: $nextBuildDirectory"
    }

    Invoke-Checked `
        -FilePath $npmCommand `
        -ArgumentList @('run', 'build') `
        -WorkingDirectory $webRoot | ForEach-Object {
            Write-Host $_
        }
}
finally {
    if ($hadNodeEnvironment) {
        $env:NODE_ENV = $previousNodeEnvironment
    }
    else {
        Remove-Item Env:NODE_ENV -ErrorAction SilentlyContinue
    }
}

Assert-NoWorkflowChanges -RepositoryRoot $repositoryRoot
Show-GitDiffSummary -RepositoryRoot $repositoryRoot

Write-Step -Message 'Fase 10 completata'
